// 可用 source.bookSourceName source.getVariable() source.setVariable()等
// java.getUserAgent() java.getWebViewUA() 目前返回内容相同
function isSourceRead() {
    return java.getUserAgent() === java.getWebViewUA()
}

// 检测 阅读 正式版
// 正式版 不支持在 JSlib 的函数直接设置默认参数
