                                }
                            }
                        }

                        if (ttsData.tts_tones && ttsData.tts_tones.length > 0) {
                            var availableTones = '';
                            for (var j = 0; j < ttsData.tts_tones.length; j++) {
                                if (j > 0) availableTones += '、';
                                availableTones += ttsData.tts_tones[j].title + '(音色ID: ' + ttsData.tts_tones[j].id + ')';
                            }
                            toneLines.push('🎧 可用音色：' + availableTones);
                        }

                        if (toneLines.length > 0) {
                            output += '\n' + toneLines.join('\n');
                        }
                    } catch (e) {}
                }

                output += `{{"\n"+"​"}}
📜 简介：${abstract}{{"\n"+"​"}}`;

                if (copyrightInfo) {
                    output += `\n📍 ${copyrightInfo.split('，')[0]}。`;
                }

                finalResult = output;
            }
        }
    } catch (e) {
    }
} else if (jjwxcSources.some(source => sourceName.includes(source))) {
    try {
        let novelId = bookIdFromBackend;

        if (novelId) {
            let currentVariable = book.getVariable("custom") || "";

            if (!currentVariable.includes("开启段评") && !currentVariable.includes("关闭段评")) {
                try {
                    let checkUrl = `https://android.jjwxc.com/app.jjwxc/android/reading/authorNovelSetting/getSetting?versionCode=381&novelid=${novelId}&setting_type=author_paragraph_comment_switch`;

                    let request = `${checkUrl},${JSON.stringify({
                        headers: {
                            "versiontype": "reading",
                            "versionCode": "381"
                        }
                    })}`;

                    let ajaxResult = java.ajax(request);
                    let checkResponse = JSON.parse(ajaxResult);

                    let paraEnabled = checkResponse.data?.paragraph_switch == "1";

                    let newVariable = currentVariable + (paraEnabled ? "开启段评" : "关闭段评");
                    book.putVariable("custom", newVariable);

                } catch(e) {
                    let newVariable = currentVariable + "关闭段评";
                    book.putVariable("custom", newVariable);
                }
            }
        }
    } catch (e) {
    }
}
finalResult;
</js>

ruleContent.callBackJs:
if (event == "clickCustomButton") {
    let targetUrl = "";

    if (chapter && chapter.url) {
        try {
            let chUrl = String(chapter.url);
            let jsMatch = chUrl.match(/"js":"book \? result : '([^']+)'"/);
            if (jsMatch && jsMatch[1]) {
                targetUrl = jsMatch[1];
            }
        } catch (e) {}
    } else if (book && book.tocUrl) {
        try {
            let tocUrl = String(book.tocUrl);
            let base64Str = tocUrl.replace(/^data:catalogUrl;base64,/, '');
            let idx = base64Str.indexOf(',');
            if (idx >= 0) base64Str = base64Str.substring(0, idx);
            let catalog = JSON.parse(java.base64Decode(base64Str));
            let source = catalog.source || "";
            let bookid = catalog.bookid || "";

            if (bookid) {
                let urlMap = {
                    "晋江": "/jj_author?novelid=" + bookid,
                    "起点": "/qd_role?bookid=" + bookid,
                    "七猫小说": "/qm_comment?type=book&book_id=" + bookid,
                    "番茄小说": "/fq_comment?book_id=" + bookid,
                    "番茄听书": "/fq_comment?book_id=" + bookid,
                    "菠萝包": "/sfacg_comment?bookid=" + bookid
                };

                if (urlMap[source]) {
                    targetUrl = getServerHost() + urlMap[source];
                }
            }
        } catch (e) {}
    }

    if (targetUrl) {
        targetUrl += "&key=" + getSecretKey();
        java.showBrowser(
            targetUrl,
            null,
            "window.java=java;",
            JSON.stringify({
                "expandedCornersRadius": 20,
                "dismissOnTouchOutside": true,
                "isDraggable": true,
                "shouldDimBackground": true,
                "backgroundDimAmount": 0.5,
                "hardwareAccelerated": true,
                "isNestedScrollingEnabled": true,
                "isGestureInsetBottomIgnored": true,
                "setFitToContents": false,
                "heightPercentage": 0.85,
                "isHideable": true
            })
        );
    } else {
        java.toast(chapter ? "当前来源不支持章评" : "当前来源不支持");
    }
    true;
}

