const categorizedData = (i) => {
  return category(i).reduce((acc, curr) => {
    const { itemKey, itemSubType, itemName, itemId } = curr;    
    const originalKey = itemSubType.includes(itemKey) ? itemKey : itemSubType;
   iTag = itemKey == "TAG"?"tagIds":itemSubType.includes("SECOND")?"secondCategoryId":"firstCategoryId";

    // 键名映射规则
    const keyMap = {
      "CATEGORY": "分类",
      "MAIN_LINE": "题材",
      "PLOT": "情节",
      "ROLE": "角色",
      "STYLE": "风格"
    };
    // 应用映射后的键名
    const categoryKey = keyMap[originalKey] || originalKey;

    // 检查分类是否已经存在
    let category = acc.find(item => item[0] === categoryKey);
    // 如果分类不存在，创建新的分类项
    if (category) {
